using EntityForge.Db.Query.Syntax.Gql;

namespace EntityForge.Db.Hosting.Tests;

public sealed partial class EntityForgeDbHostTests
{
    [TestMethod]
    public void Gql_reserved_word_inventory_rejects_bare_names_and_preserves_delimited_names()
    {
        // Reserved and pre-reserved words from ISO's published edition-1 BNF.
        // This checks identifier syntax, not the execution of each keyword.
        const string words = "ABS ABSTRACT ACOS AGGREGATE AGGREGATES ALL ALL_DIFFERENT ALTER AND ANY ARRAY AS ASC ASCENDING ASIN AT ATAN AVG BIG BIGINT BINARY BOOL BOOLEAN BOTH BTRIM BY BYTE_LENGTH BYTES CALL CARDINALITY CASE CAST CATALOG CEIL CEILING CHAR CHAR_LENGTH CHARACTER_LENGTH CHARACTERISTICS CLEAR CLONE CLOSE COALESCE COLLECT_LIST COMMIT CONSTRAINT COPY COS COSH COT COUNT CREATE CURRENT_DATE CURRENT_GRAPH CURRENT_PROPERTY_GRAPH CURRENT_ROLE CURRENT_SCHEMA CURRENT_TIME CURRENT_TIMESTAMP CURRENT_USER DATA DATE DATETIME DAY DEC DECIMAL DEGREES DELETE DESC DESCENDING DETACH DIRECTORY DISTINCT DOUBLE DROP DRYRUN DURATION DURATION_BETWEEN ELEMENT_ID ELSE END EXACT EXCEPT EXISTING EXISTS EXP FALSE FILTER FINISH FLOAT FLOAT128 FLOAT16 FLOAT256 FLOAT32 FLOAT64 FLOOR FOR FROM FUNCTION GQLSTATUS GRANT GROUP HAVING HOME_GRAPH HOME_PROPERTY_GRAPH HOME_SCHEMA HOUR IF IMPLIES IN INFINITY INSERT INSTANT INT INT128 INT16 INT256 INT32 INT64 INT8 INTEGER INTEGER128 INTEGER16 INTEGER256 INTEGER32 INTEGER64 INTEGER8 INTERSECT INTERVAL IS LEADING LEFT LET LIKE LIMIT LIST LN LOCAL LOCAL_DATETIME LOCAL_TIME LOCAL_TIMESTAMP LOG LOG10 LOWER LTRIM MATCH MAX MIN MINUTE MOD MONTH NEXT NODETACH NORMALIZE NOT NOTHING NULL NULLIF NULLS NUMBER NUMERIC OCTET_LENGTH OF OFFSET ON OPEN OPTIONAL OR ORDER OTHERWISE PARAMETER PARAMETERS PARTITION PATH PATH_LENGTH PATHS PERCENTILE_CONT PERCENTILE_DISC POWER PRECISION PROCEDURE PRODUCT PROJECT PROPERTY_EXISTS QUERY RADIANS REAL RECORD RECORDS REFERENCE REMOVE RENAME REPLACE RESET RETURN REVOKE RIGHT ROLLBACK RTRIM SAME SCHEMA SECOND SELECT SESSION SESSION_USER SET SIGNED SIN SINH SIZE SKIP SMALL SMALLINT SQRT START STDDEV_POP STDDEV_SAMP STRING SUBSTRING SUM SYSTEM_USER TAN TANH TEMPORAL THEN TIME TIMESTAMP TRAILING TRIM TRUE TYPED UBIGINT UINT UINT128 UINT16 UINT256 UINT32 UINT64 UINT8 UNION UNIQUE UNIT UNKNOWN UNSIGNED UPPER USE USMALLINT VALUE VALUES VARBINARY VARCHAR VARIABLE WHEN WHERE WHITESPACE WITH XOR YEAR YIELD ZONED ZONED_DATETIME ZONED_TIME";
        foreach (string word in words.Split(' '))
        {
            foreach (string spelling in new[] { word, word.ToLowerInvariant() })
            {
                Assert.Throws<ArgumentException>(() => GqlSyntaxParser.Parse("LET " + spelling + "=1 RETURN 1 AS answer", out _), spelling);
                Assert.Throws<ArgumentException>(() => GqlSyntaxParser.Parse("RETURN 1 AS " + spelling, out _), spelling);
                GqlSyntaxParser.Parse("RETURN 1 AS \"" + spelling + "\"", out _);
                GqlSyntaxParser.Parse("LET " + spelling + "_item=1 RETURN " + spelling + "_item AS answer", out _);
            }
        }
    }
}
